// makeSeekableBodyReplayable gives req a GetBody when its body is a seekable
// reader, so the retry transport can replay it.
//
// http.NewRequestWithContext only derives GetBody from the body types it
// recognizes (*bytes.Buffer, *bytes.Reader, *strings.Reader). A caller
// streaming an upload from an *os.File therefore produced a request the retry
// transport had to treat as non-replayable, which disabled retries entirely —
// including on 429. Bodies that cannot be rewound are left alone: replaying
// one would send a truncated request.
func makeSeekableBodyReplayable(req *http.Request, body io.Reader) error {
	if req.Body == nil || req.GetBody != nil {
		return nil
	}
	seeker, ok := body.(io.Seeker)
	if !ok {
		return nil
	}

	start, err := seeker.Seek(0, io.SeekCurrent)
	if err != nil {
		return nil
	}
	end, err := seeker.Seek(0, io.SeekEnd)
	if err != nil {
		// A failed seek leaves the offset untouched, so the body is still
		// intact; send it without retry support.
		return nil
	}
	if _, err := seeker.Seek(start, io.SeekStart); err != nil {
		// The reader is parked at EOF and cannot be rewound. Sending now
		// would upload an empty body, so fail loudly instead.
		return fmt.Errorf("rewind request body: %w", err)
	}
	if end < start {
		return nil
	}

	req.ContentLength = end - start
	// net/http closes req.Body once it has been written. Hiding the caller's
	// Closer keeps the reader usable for the next attempt, and leaves closing
	// it the caller's responsibility either way.
	req.Body = io.NopCloser(body)
	req.GetBody = func() (io.ReadCloser, error) {
		if _, err := seeker.Seek(start, io.SeekStart); err != nil {
			return nil, fmt.Errorf("rewind request body: %w", err)
		}
		return io.NopCloser(body), nil
	}
	return nil
}
